#' Omitted Variable Bias (Robustness Value)
#'
#' 
#' @param data .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param bench .
#' @param q .
#' @param direction .
#' @param kd .
#' @param h0 .
#' @param level .
#' @param plot .
#' @param plotStat .
#' @param plotLim .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$coef} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rv} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bounds} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$contour} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$coef$asDF}
#'
#' \code{as.data.frame(results$coef)}
#'
#' @export
ovb <- function(
    data,
    outcome,
    treat,
    covs,
    bench,
    q = 100,
    direction = "reduce",
    kd = "1, 2, 3",
    h0 = 0,
    level = 95,
    plot = TRUE,
    plotStat = "estimate",
    plotLim = 0.4,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("ovb requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(bench)) bench <- jmvcore::resolveQuo(jmvcore::enquo(bench))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(bench), bench, NULL))


    options <- ovbOptions$new(
        outcome = outcome,
        treat = treat,
        covs = covs,
        bench = bench,
        q = q,
        direction = direction,
        kd = kd,
        h0 = h0,
        level = level,
        plot = plot,
        plotStat = plotStat,
        plotLim = plotLim,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- ovbClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

